syntax:
#include <header>  // Includes a standard header from system directories
#include "header"  // Includes a user-defined header, searched in local directories first

// Example of include guards in a header file:
#ifndef MY_HEADER_H
#define MY_HEADER_H

// Header content: declarations, macros, etc.

#endif  // MY_HEADER_H

Implementation notes: The #include directive is a preprocessor directive, not part of the C++ language proper. The preprocessor expands it before parsing, and include guards use conditional compilation (#ifndef, #define) to ensure content is processed only once per translation unit.

code_example:
#include <iostream>

#ifndef MY_HEADER_H
#define MY_HEADER_H

namespace utils {
    extern int globalCounter;  // Declaration for external linkage
    void incrementCounter();  // Function prototype
}

#endif  // MY_HEADER_H

int main() {
    utils::incrementCounter();
    std::cout << utils::globalCounter << std::endl;
    return 0;
}
